function renderFor27b(){const id='v-for27',el=document.getElementById(id);el.innerHTML='';addBack(id);const L1=VD[id]||[],can=CTX.canEdit(id);
  el.appendChild(h('<div class="sh"><span class="eyb">Economia</span><h2>Fornitori 2027</h2><p>Per ogni fornitore: importo concordato, modalità di pagamento, rate, contratto, fatture. Un pagamento risulta fatto solo dopo la conferma del responsabile.</p><div class="big-btns" style="margin-top:12px"><button type="button" class="bb soft pdfx">⤓ Scarica in PDF</button>'+(canV('v-pag')||respPag()===CTX.user.id?'<button type="button" class="bb soft" data-go="v-pag">Calendario dei pagamenti</button>':'')+'</div></div>'));
  const tot=L1.reduce((a,r)=>a+(+r.dati.importo||0),0);let pag=0;L1.forEach(r=>(r.dati.pagamenti||[]).forEach(p=>{if(statoRata(p)[0]==='Pagato')pag+=+((p.dichiarato||{}).importo||p.importo)||0;}));
  el.appendChild(h('<div class="big3"><div class="kpi"><span>Concordato 2027</span><b>'+eur(tot)+'</b></div><div class="kpi"><span>Pagato e verificato</span><b>'+eur(pag)+'</b></div><div class="kpi dark"><span>Saldo da pagare</span><b>'+eur(tot-pag)+'</b></div></div>'));
  if(can)el.appendChild(addBtn('+ Aggiungi un fornitore 2027',()=>editFor27(null)));
  const g=h('<div class="cgrid"></div>');const fatt=VD['v-fatt']||[];
  L1.forEach(r=>{const d=r.dati;const P=d.pagamenti||[];const sp=P.reduce((a,p)=>a+(+p.importo||0),0);const pg=P.filter(p=>statoRata(p)[0]==='Pagato').reduce((a,p)=>a+(+((p.dichiarato||{}).importo||p.importo)||0),0);
    const nrm=x=>String(x||'').toLowerCase().replace(/[^a-z0-9à-ù]+/g,' ').trim();const ff=fatt.filter(f=>nrm(f.dati.soggetto)&&nrm(f.dati.soggetto).startsWith(nrm(d.fornitore).split(' ')[0]||'@@'));
    const c=h('<article class="card rc"><div class="chips"><span class="chip2 '+(d.contratto?'ok':'ko')+'">'+(d.contratto?'Contratto allegato':'Contratto da allegare')+'</span><span class="chip2">'+esc(d.modalita||(P.length>1?'A rate':'Unica soluzione'))+'</span></div><b class="vn">'+esc(d.fornitore||'')+'</b><b class="amt">'+eur(+d.importo||0)+'</b><div class="fact2"><span>Voce</span><b>'+esc(d.voce||'—')+'</b></div>'+(d.evento?'<div class="fact2"><span>Evento</span><b>'+esc(d.evento)+'</b></div>':'')+(d.resp_pag?'<div class="fact2"><span>Segue i pagamenti</span><b>'+esc(nome(d.resp_pag))+'</b></div>':'')+(d.condizioni?'<p class="muted small">'+esc(d.condizioni)+'</p>':'')+
      '<div class="fact2"><span>Pagato / residuo</span><b>'+eur(pg)+' / '+eur((+d.importo||0)-pg)+'</b></div>'+(Math.round(sp)!==Math.round(+d.importo||0)&&P.length?'<p class="neg small">Le rate sommano '+eur(sp)+', il totale concordato è '+eur(+d.importo||0)+'.</p>':'')+(ff.length?'<div class="fact2"><span>Fatture collegate</span><b>'+ff.length+'</b></div>':'')+'<div class="lab">Rate</div></article>');
    P.forEach((p,i)=>{const w=h(rataHtml({r,p,i},false));w.appendChild(bottoniRata({r,p,i},renderFor27b));if(p.dichiarato&&p.dichiarato.ricevuta)w.appendChild(fileBtn(p.dichiarato.ricevuta,'Ricevuta'));c.appendChild(w);});
    if(!P.length)c.appendChild(h('<p class="muted small">Nessuna rata: tocca «Modalità di pagamento».</p>'));
    if(d.contratto&&d.contratto.path)c.appendChild(fileBtn(d.contratto,'Contratto'));
    if(can){const b=h('<div class="rowb"><button type="button">Modalità di pagamento</button><button type="button">Modifica</button><button type="button" class="ko">Elimina</button></div>');b.children[0].addEventListener('click',()=>modalita(r));b.children[1].addEventListener('click',()=>editFor27(r));b.children[2].addEventListener('click',()=>ask('Eliminare «'+(d.fornitore||'')+'»?','Elimina',async()=>{await CTX.sb.from('voci_dati').delete().eq('id',r.id);await loadVD();renderFor27b();}));c.appendChild(b);
      if(!d.contratto){const u=h('<label class="bb soft sm upl">Allega il contratto<input type="file" accept=".pdf,image/*" hidden></label>');u.querySelector('input').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;const k=await carica(f,id);await CTX.sb.from('voci_dati').update({dati:Object.assign({},d,{contratto:k}),aggiornato:new Date().toISOString()}).eq('id',r.id);await loadVD();renderFor27b();});c.appendChild(u);}}
    g.appendChild(c);});el.appendChild(g);if(!L1.length)el.appendChild(h('<div class="card soon"><p>Ancora nessun fornitore 2027.</p></div>'));}
function modalita(r){const d=JSON.parse(JSON.stringify(r.dati));const ppl=Object.values(PEOPLE);const P=d.pagamenti||[];
  const rowR=(x)=>'<div class="prow"><input type="text" class="pn2" value="'+esc(x.n||'')+'" placeholder="Acconto, rata, saldo…"><input type="date" class="pd" value="'+esc(x.data||'')+'"><input type="number" class="pi" step="any" value="'+esc(x.importo===''||x.importo==null?'':x.importo)+'" placeholder="€"><button type="button" class="px">×</button></div>';
  const dl=sheet('Modalità di pagamento · '+(d.fornitore||''),'<div class="ctl"><label for="mp_t">Importo complessivo concordato (€)</label><input type="number" id="mp_t" step="any" value="'+esc(d.importo||'')+'"></div><div class="ctl"><label for="mp_m">Modalità</label><select id="mp_m">'+['Unica soluzione','A rate','Acconto e saldo'].map(x=>'<option'+(x===d.modalita?' selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="ctl"><label for="mp_e">Evento o attività</label><input type="text" id="mp_e" value="'+esc(d.evento||'')+'"></div><div class="ctl"><label for="mp_r">Chi segue i pagamenti</label><select id="mp_r"><option value="">'+(respPag()?'Il responsabile generale ('+esc(nome(respPag()))+')':'Nessuno')+'</option>'+ppl.map(p=>'<option value="'+p.id+'"'+(p.id===d.resp_pag?' selected':'')+'>'+esc(p.nome||p.email)+'</option>').join('')+'</select></div><div class="ctl"><label for="mp_c">Condizioni concordate</label><textarea id="mp_c">'+esc(d.condizioni||'')+'</textarea></div><div class="lab">Rate (descrizione, data, importo)</div><div class="plist">'+P.map(rowR).join('')+'</div><button type="button" class="lnk2" id="mp_add">+ Aggiungi una rata</button><button type="button" class="lnk2" id="mp_div">Dividi il totale in parti uguali</button><p class="tot small"></p>','Salva',async(x)=>{
    const rows=[...x.querySelectorAll('.prow')];const np=rows.map((rw,k)=>{const old=P[k]||{};return Object.assign({},old,{n:rw.querySelector('.pn2').value.trim(),data:rw.querySelector('.pd').value,importo:rw.querySelector('.pi').value===''?'':+rw.querySelector('.pi').value});}).filter(z=>z.n||z.data||z.importo!=='');
    const o=Object.assign({},d,{importo:+x.querySelector('#mp_t').value||0,modalita:x.querySelector('#mp_m').value,evento:x.querySelector('#mp_e').value.trim(),resp_pag:x.querySelector('#mp_r').value,condizioni:x.querySelector('#mp_c').value.trim(),pagamenti:np});
    const {error}=await CTX.sb.from('voci_dati').update({dati:o,aggiornato:new Date().toISOString()}).eq('id',r.id);if(error)throw new Error(error.message);
    const nuove=np.filter((z,k)=>!P[k]||P[k].data!==z.data||P[k].importo!==z.importo);const chi=o.resp_pag||respPag();if(nuove.length&&chi&&chi!==CTX.user.id)await avvisaUtente(chi,'Nuove scadenze di pagamento per '+o.fornitore+' ('+nuove.length+')','v-pag');
    await loadVD();renderFor27b();});
  const pl=dl.querySelector('.plist');const tot=()=>{const s=[...pl.querySelectorAll('.pi')].reduce((a,i)=>a+(+i.value||0),0);const t=+dl.querySelector('#mp_t').value||0;dl.querySelector('.tot').innerHTML='Totale rate: <b>'+eur(s)+'</b>'+(Math.round(s)!==Math.round(t)?' <span class="neg">— diverso dal concordato ('+eur(t)+')</span>':' ✓');};
  pl.addEventListener('click',e=>{if(e.target.classList.contains('px')){e.target.closest('.prow').remove();tot();}});pl.addEventListener('input',tot);dl.querySelector('#mp_t').addEventListener('input',tot);
  dl.querySelector('#mp_add').addEventListener('click',()=>{pl.appendChild(h(rowR({})));tot();});
  dl.querySelector('#mp_div').addEventListener('click',()=>{const t=+dl.querySelector('#mp_t').value||0;const rs=[...pl.querySelectorAll('.prow')];if(!rs.length||!t)return;const part=Math.floor(t/rs.length*100)/100;rs.forEach((rw,k)=>{rw.querySelector('.pi').value=k===rs.length-1?Math.round((t-part*(rs.length-1))*100)/100:part;});tot();});tot();}
function renderPag(){const id='v-pag',el=document.getElementById(id);el.innerHTML='';addBack(id);
  el.appendChild(h('<div class="sh"><span class="eyb">Economia</span><h2>Pagamenti ai fornitori</h2><p>Tutte le rate in ordine di data. Chi paga registra il pagamento con la ricevuta; il responsabile'+(respPag()?' ('+esc(nome(respPag()))+')':'')+' lo conferma o chiede una correzione.</p><div class="big-btns" style="margin-top:12px"><button type="button" class="bb soft pdfx">⤓ Scarica in PDF</button></div></div>'));
  if(!respPag())el.appendChild(h('<div class="card hot"><p style="margin:0">Non è stato ancora scelto il responsabile dei pagamenti: lo sceglie l’amministratore in Utenti e accessi → Impostazioni.</p></div>'));
  const X=righeRate();const by={};X.forEach(x=>{const s=statoRata(x.p)[0];(by[s]=by[s]||[]).push(x);});
  const sum=s=>(by[s]||[]).reduce((a,x)=>a+(+x.p.importo||0),0);
  el.appendChild(h('<div class="big3"><div class="kpi"><span>Da confermare</span><b>'+(by['In attesa di conferma']||[]).length+'</b></div><div class="kpi"><span>In scadenza (7 giorni)</span><b>'+eur(sum('In scadenza'))+'</b></div><div class="kpi dark"><span>In ritardo</span><b class="'+(sum('In ritardo')?'neg':'')+'">'+eur(sum('In ritardo'))+'</b></div></div>'));
  ['In attesa di conferma','Da correggere','In ritardo','In scadenza','Da pagare','Pagato'].forEach(s=>{const L1=by[s]||[];if(!L1.length)return;el.appendChild(h('<h3 class="gh">'+s+' · '+L1.length+'</h3>'));const c=h('<section class="card"></section>');
    L1.forEach(x=>{const w=h(rataHtml(x,true));w.appendChild(bottoniRata(x,renderPag));if(x.p.dichiarato&&x.p.dichiarato.ricevuta)w.appendChild(fileBtn(x.p.dichiarato.ricevuta,'Ricevuta'));c.appendChild(w);});el.appendChild(c);});
  if(!X.length)el.appendChild(h('<div class="card soon"><p>Nessuna rata. Le rate si inseriscono nei Fornitori 2027 → «Modalità di pagamento».</p></div>'));}

/* --- 27. Cosa serve per questo evento? --- */
const CATS=[['Allestimenti e strutture',/palc|pedan|tensostr|gazebo|struttur|allestim|tribun/],['Service audio',/audio|fonic|amplific|casse|microfon|impianto (audio|voci)/],['Service luci',/luci\b|luce\b|illumin|faro|fari\b|lighting/],['Allestimenti e delimitazioni',/transenn|recinz|delimit|barrier/],
  ['Servizi igienici',/bagn|wc|servizi igienici/],['Sicurezza e steward',/sicurezz|steward|vigilan|security/],['Assistenza sanitaria',/ambulan|soccors|sanitar|medic/],['Pulizia',/pulizi|rifiut|igiene urbana/],['Pirotecnica',/fuoc|pirotec|botti/],['Luminarie',/luminari/],
  ['Stampa e grafica',/stamp|manifest|locandin|grafic|tipograf|striscion|banner/],['Video, LED wall e diretta',/video|ledwall|led wall|diretta|streaming|maxischerm|riprese/],['Ristorazione',/catering|rinfresc|buffet|ristor|cibo|bevand/],['Trasporti',/trasport|navett|bus\b|furgon/],
  ['Noleggio arredi',/sedi[ae]|tavol|arred|noleggi/],['Impianti elettrici',/generator|elettric|corrente|quadro/],['Diritti e permessi',/siae|permess|autorizzaz/],['Foto e video',/fotograf|foto\b/],['Artisti e musica',/band[ae]\b|music|artist|concert|orchestr|cantant/],['Fiori e addobbi',/fior|addobb/]];
function riconosci(t){const parti=String(t||'').toLowerCase().split(/[,;\n]|\be\b|\bpoi\b|\binoltre\b/).map(s=>s.trim()).filter(s=>s.length>1);const out=[];
  parti.forEach(p=>{const c=CATS.find(([,re])=>re.test(p));const es=p.replace(/^(mi |ci )?(servono|serve|occorrono|occorre|vorrei|per questo evento)\s*/,'').replace(/^(un|una|uno|il|lo|la|i|gli|le|dei|delle|degli)\s+/,'').replace(/^(l|un|dell|all)[’']\s*/,'').trim();if(!es)return;out.push({esigenza:es.charAt(0).toUpperCase()+es.slice(1),categoria:c?c[0]:'Altro'});});
  return out.filter((x,i)=>out.findIndex(y=>y.esigenza===x.esigenza)===i);}
function candidati(cat){const re=(CATS.find(c=>c[0]===cat)||[])[1];const out=[];if(!re)return out;
  (D.forn||[]).forEach(f=>{if(re.test((f.att+' '+f.n).toLowerCase()))out.push({nome:f.n,servizi:f.att,dove:f.loc,storico:'Fornitore 2026 · '+eur(f.v),fonte:'2026'});});
  (VD['v-for27']||[]).forEach(r=>{const t=(r.dati.voce+' '+r.dati.fornitore).toLowerCase();if(re.test(t)&&!out.some(o=>o.nome===r.dati.fornitore))out.push({nome:r.dati.fornitore,servizi:r.dati.voce,storico:'Fornitore 2027 · '+eur(+r.dati.importo||0),fonte:'2027'});});
  (VD['v-prev']||[]).forEach(r=>{const t=(r.dati.voce+' '+(r.dati.fornitore||'')).toLowerCase();if(r.dati.fornitore&&re.test(t)){const o=out.find(x=>x.nome===r.dati.fornitore);const s='preventivo '+(+r.dati.importo?eur(+r.dati.importo):'')+(r.dati.qualita?' · qualità '+String(r.dati.qualita).charAt(0)+'/5':'');if(o)o.storico+=' · '+s;else out.push({nome:r.dati.fornitore,servizi:r.dati.voce,storico:s,fonte:'preventivi'});}});
  return out;}
function cosaServe(e){const ev=e||{};const nomeEv=ev.n||'evento';let ES=[];const ppl=Object.values(PEOPLE);
  const dl=sheet('Cosa serve per «'+nomeEv+'»?','<div class="ctl"><label for="cs_t">Scrivi con parole semplici</label><textarea id="cs_t" placeholder="Per esempio: mi servono un palco, l’impianto audio, le luci e le transenne"></textarea></div><div class="big-btns"><button type="button" class="bb dark sm" id="cs_r">Riconosci le esigenze</button>'+(AION?'<button type="button" class="bb soft sm" id="cs_ai">Chiedi all’assistente</button>':'')+'</div><div class="eslist"></div><div class="fornlist"></div><p class="gmsg" id="cs_m"></p>','Chiudi',async()=>{});
  const L=dl.querySelector('.eslist'),F=dl.querySelector('.fornlist'),M=dl.querySelector('#cs_m');
  const drawE=()=>{L.innerHTML='';if(!ES.length)return;L.appendChild(h('<div class="lab">Esigenze riconosciute (puoi correggerle)</div>'));
    ES.forEach((x,i)=>{const r=h('<div class="vrow"><input type="text" value="'+esc(x.esigenza)+'"><select>'+CATS.map(c=>'<option'+(c[0]===x.categoria?' selected':'')+'>'+c[0]+'</option>').join('')+'<option'+(x.categoria==='Altro'?' selected':'')+'>Altro</option></select><button type="button" class="px">×</button></div>');
      r.querySelector('input').addEventListener('input',ev2=>x.esigenza=ev2.target.value);r.querySelector('select').addEventListener('change',ev2=>x.categoria=ev2.target.value);r.querySelector('.px').addEventListener('click',()=>{ES.splice(i,1);drawE();});L.appendChild(r);});
    const a=h('<div class="big-btns"><button type="button" class="lnk2">+ Aggiungi un’esigenza</button><button type="button" class="bb dark sm">Trova fornitori</button></div>');a.children[0].addEventListener('click',()=>{ES.push({esigenza:'',categoria:'Altro'});drawE();});a.children[1].addEventListener('click',drawF);L.appendChild(a);};
  const drawF=()=>{F.innerHTML='';const vuote=[];const grp={};ES.filter(x=>x.esigenza.trim()).forEach(x=>{(grp[x.categoria]=grp[x.categoria]||[]).push(x.esigenza);});
    const tutti={};Object.keys(grp).forEach(cat=>{const C=candidati(cat);if(!C.length)vuote.push(cat);C.forEach(c=>{(tutti[c.nome]=tutti[c.nome]||{c,cats:new Set()}).cats.add(cat);});
      const s=h('<section class="fsel"><div class="lab">'+esc(cat)+' <span class="muted small">('+esc(grp[cat].join(', '))+')</span></div></section>');
      if(!C.length)s.appendChild(h('<p class="muted small">Nessun fornitore in archivio per questo servizio: puoi comunque chiedere un preventivo a un fornitore nuovo.</p>'));
      C.forEach(c=>{const multi=Object.keys(grp).filter(k=>candidati(k).some(z=>z.nome===c.nome));s.appendChild(h('<label class="fcand"><input type="checkbox" data-cat="'+esc(cat)+'" value="'+esc(c.nome)+'"><span><b>'+esc(c.nome)+'</b>'+(multi.length>1?' <span class="chip2 ok">fa anche '+esc(multi.filter(k=>k!==cat).join(', '))+'</span>':'')+'<br><span class="muted small">'+esc(c.servizi||'')+(c.dove?' · '+esc(c.dove):'')+' · '+esc(c.storico||'')+'</span></span></label>'));});
      s.appendChild(h('<label class="fcand"><input type="checkbox" data-cat="'+esc(cat)+'" value=""><span>Un fornitore nuovo da trovare</span></label>'));F.appendChild(s);});
    if(!Object.keys(grp).length){M.textContent='Scrivi almeno un’esigenza.';return;}
    M.className='gmsg';M.textContent=vuote.length?'Senza fornitore in archivio: '+vuote.join(', ')+'.':'';
    if(AION){const b=h('<button type="button" class="lnk2">Chiedi all’assistente un consiglio su questi fornitori</button>');const out=h('<div class="aibox" hidden></div>');b.addEventListener('click',async()=>{b.textContent='L’assistente sta pensando…';const x=await ai('fornitori_evento',{evento:nomeEv,esigenze:ES,candidati:Object.values(tutti).map(t=>({nome:t.c.nome,servizi:t.c.servizi,storico:t.c.storico,categorie:[...t.cats]}))});b.remove();out.hidden=false;out.innerHTML=x.err?esc(x.err):'<p>'+testoAI(x.testo)+'</p><span class="aisig">Scritto dall’assistente sui fornitori presenti in archivio.</span>';});F.appendChild(b);F.appendChild(out);}
    const form=h('<section class="fsel"><div class="lab">Per le richieste di preventivo</div><div class="when"><div class="ctl"><label for="cs_p">Chi chiede i preventivi</label><select id="cs_p">'+ppl.map(p=>'<option value="'+p.id+'"'+(p.id===CTX.user.id?' selected':'')+'>'+esc(p.nome||p.email)+(p.id===CTX.user.id?' (io)':'')+'</option>').join('')+'</select></div><div class="ctl"><label for="cs_d">Data del servizio</label><input type="date" id="cs_d" value="'+esc((typeof evDays==='function'&&ev.id&&(evDays(ev)||[])[0])||'')+'"></div></div><div class="when"><div class="ctl"><label for="cs_q">Quantità o dettagli</label><input type="text" id="cs_q" placeholder="Per esempio: palco 8x6, 40 transenne"></div><div class="ctl"><label for="cs_i">Importo previsto (€)</label><input type="number" id="cs_i"></div></div><button type="button" class="bb dark" id="cs_go">Richiedi preventivo ai selezionati</button></section>');F.appendChild(form);
    form.querySelector('#cs_go').addEventListener('click',async()=>{const sel=[...F.querySelectorAll('.fcand input:checked')].map(i=>({cat:i.dataset.cat,forn:i.value}));if(!sel.length){M.textContent='Seleziona almeno un fornitore (o «fornitore nuovo»).';return;}
      const chi=form.querySelector('#cs_p').value;const dett=form.querySelector('#cs_q').value.trim(),dd=form.querySelector('#cs_d').value,ip=form.querySelector('#cs_i').value;
      const rows=sel.map(s=>({voce:'v-prev',dati:{voce:'Evento '+nomeEv+' – '+s.cat,fornitore:s.forn,importo:'',importo_previsto:ip,stato:'Da chiedere',chi,entro:'',evento:nomeEv,evento_id:ev.id||'',quantita:dett,data_servizio:dd,esigenze:grp[s.cat].join(', ')}}));
      const {error}=await CTX.sb.from('voci_dati').insert(rows);if(error){M.textContent=error.message;return;}
      await CTX.sb.from('compiti').insert({per:chi,titolo:'Chiedi '+rows.length+(rows.length===1?' preventivo':' preventivi')+' per «'+nomeEv+'»: '+[...new Set(sel.map(s=>s.cat))].join(', '),area:'v-prev'});
      const L1=VD['s-ev']||[];const rr=ev.id!=null&&L1.find(x=>x.dati.evid===String(ev.id));if(rr&&CTX.canEdit('s-ev')){const fo=(rr.dati.fornitori||[]).concat(sel.map(s=>({servizio:s.cat,fornitore:s.forn,quantita:dett,data:dd,importo:ip,stato:'Preventivo richiesto',resp:chi})));await CTX.sb.from('voci_dati').update({dati:Object.assign({},rr.dati,{fornitori:fo})}).eq('id',rr.id);}
      await Promise.all([loadVD(),loadSocial()]);dl.remove();stEl.textContent=(rows.length===1?'Creata 1 richiesta':'Create '+rows.length+' richieste')+' di preventivo: '+nome(chi)+' riceve il compito.';});};
  dl.querySelector('#cs_r').addEventListener('click',()=>{ES=riconosci(dl.querySelector('#cs_t').value);if(!ES.length){M.textContent='Non ho riconosciuto nulla: scrivi le cose separate da virgole.';return;}M.textContent='';drawE();});
  const aib=dl.querySelector('#cs_ai');if(aib)aib.addEventListener('click',async()=>{const t=dl.querySelector('#cs_t').value.trim();if(!t)return;aib.textContent='L’assistente legge…';const x=await ai('esigenze',{testo:t,categorie:CATS.map(c=>c[0])});aib.textContent='Chiedi all’assistente';
    try{const j=JSON.parse((x.testo||'').match(/\[[\s\S]*\]/)[0]);ES=j.filter(z=>z&&z.esigenza).map(z=>({esigenza:String(z.esigenza),categoria:CATS.some(c=>c[0]===z.categoria)?z.categoria:'Altro'}));drawE();}catch(err){ES=riconosci(t);drawE();M.textContent='L’assistente non ha risposto bene: uso il riconoscimento automatico.';}});}
chiediFornEvento=cosaServe;

/* --- 25. Chat --- */
let CONV=[],PART=[],MSG={},CHQ='';
async function loadChat(){if(!CTX.sb)return;try{await CTX.sb.rpc('unisciti_aree');}catch(e){}
  const [c,p,m]=await Promise.all([CTX.sb.from('conversazioni').select('*').order('ultimo',{ascending:false}),CTX.sb.from('partecipanti').select('*'),CTX.sb.from('messaggi').select('*').order('quando',{ascending:false}).limit(400)]);
  CONV=c.data||[];PART=p.data||[];MSG={};(m.data||[]).slice().reverse().forEach(x=>(MSG[x.conv_id]=MSG[x.conv_id]||[]).push(x));}
const mioPart=cid=>PART.find(p=>p.conv_id===cid&&p.user_id===CTX.user.id);
const nonLetti=cid=>{const mp=mioPart(cid);return (MSG[cid]||[]).filter(m=>m.da!==CTX.user.id&&(!mp||m.quando>mp.ultimo_letto)).length;};
const titoloConv=c=>{if(c.tipo==='privata'){const o=PART.find(p=>p.conv_id===c.id&&p.user_id!==CTX.user.id);return o?nome(o.user_id):(c.titolo||'Conversazione');}return c.titolo||'Gruppo';};
function chatBadge(){const n=CONV.reduce((a,c)=>a+nonLetti(c.id),0);document.querySelectorAll('.nv[data-go="p-chat"]').forEach(b=>{let s=b.querySelector('.nb');if(!s){s=h('<span class="nb"></span>');b.appendChild(s);}s.textContent=n||'';s.hidden=!n;});return n;}
async function renderChat(){const el=document.getElementById('p-chat');el.innerHTML='';if(CHATSEL&&CONV.find(c=>c.id===CHATSEL))return apriConv(el,CONV.find(c=>c.id===CHATSEL));CHATSEL=null;
  el.appendChild(h('<div class="sh"><span class="eyb">Comunicazione</span><h2>Chat</h2><p>Conversazioni a due, gruppi e i gruppi delle aree. Le vedono solo i partecipanti.</p></div>'));
  const top=h('<div class="big-btns"><button type="button" class="bb dark">Nuova conversazione</button><button type="button" class="bb soft">Nuovo gruppo</button></div>');top.children[0].addEventListener('click',()=>nuovaConv('privata'));top.children[1].addEventListener('click',()=>nuovaConv('gruppo'));el.appendChild(top);
  const sr=h('<div class="ctl"><label for="ch_q">Cerca nei messaggi</label><input type="search" id="ch_q" value="'+esc(CHQ)+'" placeholder="Scrivi una parola…"></div>');el.appendChild(sr);const res=h('<div></div>');el.appendChild(res);
  sr.querySelector('input').addEventListener('input',async e=>{CHQ=e.target.value.trim();res.innerHTML='';if(CHQ.length<2)return;const {data}=await CTX.sb.from('messaggi').select('*').ilike('testo','%'+CHQ+'%').order('quando',{ascending:false}).limit(30);
    const c=h('<section class="card"><h3>Risultati</h3></section>');(data||[]).forEach(m=>{const cv=CONV.find(x=>x.id===m.conv_id);const b=h('<button type="button" class="calit" style="--c:#24478F"><i></i><span><b>'+esc(cv?titoloConv(cv):'')+'</b><em>'+esc(nome(m.da))+': '+esc(m.testo||'').slice(0,120)+'</em></span></button>');b.addEventListener('click',()=>{CHATSEL=m.conv_id;renderChat();});c.appendChild(b);});if(!(data||[]).length)c.appendChild(h('<p class="muted">Nessun messaggio trovato.</p>'));res.appendChild(c);});
  const l=h('<section class="card"></section>');CONV.forEach(c=>{const ms=MSG[c.id]||[];const u=ms[ms.length-1];const n=nonLetti(c.id);
    const b=h('<button type="button" class="convr"><span class="av">'+esc(titoloConv(c).charAt(0).toUpperCase())+'</span><span class="cvt"><b>'+esc(titoloConv(c))+(c.tipo==='area'?' <span class="chip2">area</span>':'')+'</b><em>'+(u?esc(nome(u.da).split(' ')[0])+': '+esc((u.testo||'Allegato').slice(0,60)):'Nessun messaggio')+'</em></span>'+(n?'<span class="nb">'+n+'</span>':'')+'</button>');
    b.addEventListener('click',()=>{CHATSEL=c.id;renderChat();});l.appendChild(b);});
  if(!CONV.length)l.appendChild(h('<p class="muted">Ancora nessuna conversazione.</p>'));el.appendChild(l);chatBadge();}
function nuovaConv(tipo){const ppl=Object.values(PEOPLE).filter(p=>p.id!==CTX.user.id);
  sheet(tipo==='privata'?'Nuova conversazione':'Nuovo gruppo',(tipo==='gruppo'?'<div class="ctl"><label for="nc_t">Nome del gruppo</label><input type="text" id="nc_t"></div><div class="lab">Partecipanti</div>':'<div class="lab">Con chi</div>')+'<div class="checks">'+ppl.map(p=>'<label><input type="'+(tipo==='privata'?'radio" name="nc_p':'checkbox')+'" value="'+p.id+'"> '+esc(p.nome||p.email)+'</label>').join('')+'</div>','Apri',async(dl)=>{
    const sel=[...dl.querySelectorAll('.checks input:checked')].map(x=>x.value);if(!sel.length){dl.querySelector('.smsg').textContent='Scegli almeno una persona.';return false;}
    if(tipo==='privata'){const es=CONV.find(c=>c.tipo==='privata'&&PART.some(p=>p.conv_id===c.id&&p.user_id===sel[0]));if(es){CHATSEL=es.id;renderChat();return;}}
    const t=tipo==='gruppo'?(dl.querySelector('#nc_t').value.trim()||'Gruppo'):null;const {data,error}=await CTX.sb.from('conversazioni').insert({titolo:t,tipo}).select().single();if(error)throw new Error(error.message);
    const r2=await CTX.sb.from('partecipanti').insert([CTX.user.id].concat(sel).map(u=>({conv_id:data.id,user_id:u})));if(r2.error)throw new Error(r2.error.message);
    await loadChat();CHATSEL=data.id;renderChat();});}
async function apriConv(el,c){const me=CTX.user.id;const memb=PART.filter(p=>p.conv_id===c.id).map(p=>p.user_id);
  const b=h('<button type="button" class="back">‹ Tutte le chat</button>');b.addEventListener('click',()=>{CHATSEL=null;renderChat();});el.appendChild(b);
  el.appendChild(h('<div class="sh"><h2>'+esc(titoloConv(c))+'</h2><p class="muted small">'+esc(memb.map(nome).join(', '))+'</p></div>'));
  const box=h('<section class="card chatbox"></section>');el.appendChild(box);
  const draw=()=>{box.innerHTML='';(MSG[c.id]||[]).forEach(m=>{const mio=m.da===me;const t=esc(m.testo||'').replace(/@([A-Za-zÀ-ÿ'’]+(?: [A-Za-zÀ-ÿ'’]+)?)/g,'<b class="men">@$1</b>');
      const w=h('<div class="msg'+(mio?' mio':'')+'">'+(mio?'':'<span class="mda">'+esc(nome(m.da))+'</span>')+(t?'<span class="mtx">'+t.replace(/\n/g,'<br>')+'</span>':'')+'<em>'+new Date(m.quando).toLocaleString('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+'</em></div>');
      if(m.allegato&&m.allegato.path){if(/\.(png|jpe?g|gif|webp|heic)$/i.test(m.allegato.nome||'')){const im=h('<img class="mimg" alt="'+esc(m.allegato.nome)+'">');firmata(m.allegato).then(u=>{if(u)im.src=u;});im.addEventListener('click',()=>apriFile(m.allegato));w.insertBefore(im,w.querySelector('em'));}else w.insertBefore(fileBtn(m.allegato),w.querySelector('em'));}
      if(m.collegamento&&m.collegamento.go){const l=h('<button type="button" class="lnk2">'+esc(m.collegamento.titolo||'Apri')+'</button>');l.addEventListener('click',()=>go(m.collegamento.go));w.insertBefore(l,w.querySelector('em'));}
      if(mio){const x=h('<button type="button" class="mdel" aria-label="Elimina">×</button>');x.addEventListener('click',()=>ask('Eliminare il messaggio?','Elimina',async()=>{await CTX.sb.from('messaggi').delete().eq('id',m.id);MSG[c.id]=MSG[c.id].filter(z=>z.id!==m.id);draw();}));w.appendChild(x);}
      box.appendChild(w);});if(!(MSG[c.id]||[]).length)box.appendChild(h('<p class="muted">Scrivi il primo messaggio.</p>'));box.scrollTop=box.scrollHeight;};
  draw();CHATDRAW=draw;CHATOPEN=c.id;
  const comp=h('<section class="card composer"><div class="mentions" hidden></div><div class="collega" hidden></div><textarea id="ch_t" rows="2" placeholder="Scrivi un messaggio… (usa @ per menzionare)"></textarea><div class="crow"><label class="bb soft sm upl">Allegato<input type="file" hidden id="ch_f"></label><button type="button" class="bb soft sm" id="ch_at">@</button><button type="button" class="bb soft sm" id="ch_l">Collega</button><button type="button" class="bb dark" id="ch_s">Invia</button></div><span class="muted small" id="ch_info"></span></section>');el.appendChild(comp);
  let file=null,coll=null;const menz=new Set();const info=comp.querySelector('#ch_info');const upd=()=>{info.textContent=[file?'Allegato: '+file.name:'',coll?'Collegato a: '+coll.titolo:'',menz.size?'Menzioni: '+[...menz].map(nome).join(', '):''].filter(Boolean).join(' · ');};
  comp.querySelector('#ch_f').addEventListener('change',e=>{file=e.target.files[0]||null;upd();});
  const mn=comp.querySelector('.mentions');comp.querySelector('#ch_at').addEventListener('click',()=>{mn.hidden=!mn.hidden;mn.innerHTML='';memb.filter(u=>u!==me).forEach(u=>{const bb=h('<button type="button" class="chip2">'+esc(nome(u))+'</button>');bb.addEventListener('click',()=>{const t=comp.querySelector('#ch_t');t.value+=(t.value&&!t.value.endsWith(' ')?' ':'')+'@'+nome(u)+' ';menz.add(u);mn.hidden=true;upd();t.focus();});mn.appendChild(bb);});});
  const cl=comp.querySelector('.collega');comp.querySelector('#ch_l').addEventListener('click',()=>{cl.hidden=!cl.hidden;cl.innerHTML='';const op=[].concat(COMP.filter(x=>!x.fatto&&(x.per===me||x.da===me)).map(x=>({titolo:'Compito: '+x.titolo,go:'p-me'})),RICH.filter(x=>x.stato!=='fatta').map(x=>({titolo:'Richiesta: '+x.titolo,go:'p-req'})),(canV('s-ev')&&typeof allEv==='function'?allEv():[]).slice(0,30).map(x=>({titolo:'Evento: '+x.n,go:'p-cal'})),vperc().map(x=>({titolo:'Percorso: '+x.dati.nome,go:x.dati.stato==='Pubblicato'?'p-pub':'v-perc'})));
    op.slice(0,60).forEach(o=>{const bb=h('<button type="button" class="chip2">'+esc(o.titolo)+'</button>');bb.addEventListener('click',()=>{coll=o;cl.hidden=true;upd();});cl.appendChild(bb);});if(!op.length)cl.appendChild(h('<span class="muted small">Niente da collegare.</span>'));});
  comp.querySelector('#ch_s').addEventListener('click',async()=>{const t=comp.querySelector('#ch_t').value.trim();if(!t&&!file)return;const sb=comp.querySelector('#ch_s');sb.disabled=true;
    try{const al=file?await carica(file,'chat/'+me):null;memb.forEach(u=>{if(u!==me&&t.includes('@'+nome(u)))menz.add(u);});
      const {data,error}=await CTX.sb.from('messaggi').insert({conv_id:c.id,testo:t||null,allegato:al,collegamento:coll,menzioni:[...menz]}).select().single();if(error)throw new Error(error.message);
      (MSG[c.id]=MSG[c.id]||[]).push(data);comp.querySelector('#ch_t').value='';file=null;coll=null;menz.clear();upd();draw();}catch(e){stEl.textContent=e.message;}sb.disabled=false;});
  segnaLetta(c.id);}
let CHATDRAW=null,CHATOPEN=null;
async function segnaLetta(cid){const now=new Date().toISOString();const mp=mioPart(cid);if(mp)mp.ultimo_letto=now;await CTX.sb.from('partecipanti').update({ultimo_letto:now}).eq('conv_id',cid).eq('user_id',CTX.user.id);
  const ns=NOTI.filter(n=>n.link==='p-chat#'+cid&&!n.letto);if(ns.length){ns.forEach(n=>n.letto=true);await CTX.sb.from('notifiche').update({letto:true}).eq('per',CTX.user.id).eq('link','p-chat#'+cid);refreshBell();}chatBadge();}

/* --- 25. Bacheca --- */
let AVV=[],LET=[];const TIPI_AVV=['Avviso','Comunicazione del Presidente','Convocazione','Aggiornamento organizzativo','Scadenza importante','Documento'];
async function loadBach(){if(!CTX.sb)return;const [a,l]=await Promise.all([CTX.sb.from('avvisi').select('*').order('quando',{ascending:false}).limit(100),CTX.sb.from('letture').select('*')]);AVV=a.data||[];LET=l.data||[];}
const letto=a=>LET.some(l=>l.avviso_id===a.id&&l.user_id===CTX.user.id)||a.autore===CTX.user.id;
async function renderBach(){const el=document.getElementById('p-bach');el.innerHTML='';const me=CTX.user.id;
  el.appendChild(h('<div class="sh"><span class="eyb">Comunicazione</span><h2>Bacheca</h2><p>Avvisi, comunicazioni del Presidente, convocazioni, scadenze e documenti ufficiali.</p><div class="big-btns" style="margin-top:12px"><button type="button" class="bb soft pdfx">⤓ Scarica in PDF</button></div></div>'));
  if(isPres())el.appendChild(addBtn('+ Pubblica in bacheca',nuovoAvviso));
  const ord=AVV.slice().sort((a,b)=>(b.fissato-a.fissato)||String(b.quando).localeCompare(String(a.quando)));
  const auto=ord.filter(a=>!a.conferma&&!letto(a));if(auto.length){await CTX.sb.from('letture').upsert(auto.map(a=>({avviso_id:a.id,user_id:me})),{onConflict:'avviso_id,user_id',ignoreDuplicates:true});auto.forEach(a=>LET.push({avviso_id:a.id,user_id:me}));}
  const g=h('<div class="bach"></div>');ord.forEach(a=>{const c=h('<article class="card rc'+(a.fissato?' fis':'')+(a.importante?' hot':'')+'"><div class="chips">'+(a.fissato?'<span class="chip2">In evidenza</span>':'')+'<span class="chip2">'+esc(a.tipo)+'</span>'+(a.importante?'<span class="chip2 ko">Importante</span>':'')+(a.conferma?'<span class="chip2 '+(letto(a)?'ok':'ko')+'">'+(letto(a)?'Lettura confermata':'Conferma la lettura')+'</span>':'')+'</div><b class="vn">'+esc(a.titolo)+'</b>'+(a.testo?'<p style="white-space:pre-line;margin:0">'+esc(a.testo)+'</p>':'')+'<span class="muted small">'+esc(nome(a.autore))+' · '+new Date(a.quando).toLocaleString('it-IT',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})+(a.tutti?' · per tutti':' · per '+[].concat((a.aree||[]).map(k=>SECN[k]?SECN[k].n:k),(a.utenti||[]).map(nome)).join(', '))+'</span></article>');
    (a.allegati||[]).forEach(f=>c.appendChild(fileBtn(f)));
    if(a.conferma&&!letto(a)){const b=h('<button type="button" class="bb dark">Ho letto</button>');b.addEventListener('click',async()=>{await CTX.sb.from('letture').insert({avviso_id:a.id});LET.push({avviso_id:a.id,user_id:me});renderBach();});c.appendChild(b);}
    if(a.autore===me||CTX.admin){const bx=h('<div class="rowb"><button type="button">Chi ha letto</button><button type="button">'+(a.fissato?'Togli dall’evidenza':'Metti in evidenza')+'</button><button type="button" class="ko">Elimina</button></div>');
      bx.children[0].addEventListener('click',async()=>{const {data,error}=await CTX.sb.rpc('destinatari_avviso',{aid:a.id});const L1=data||[];const si=L1.filter(x=>x.letto),no=L1.filter(x=>!x.letto);
        sheet('Letture: '+a.titolo,error?'<p>'+esc(error.message)+'</p>':'<p><b>Hanno letto ('+si.length+')</b><br>'+(si.map(x=>esc(x.nome)+' <span class="muted small">'+new Date(x.letto).toLocaleDateString('it-IT')+'</span>').join('<br>')||'nessuno')+'</p><p><b>Non ancora ('+no.length+')</b><br>'+(no.map(x=>esc(x.nome)).join('<br>')||'nessuno')+'</p>','Chiudi',async()=>{});});
      bx.children[1].addEventListener('click',async()=>{await CTX.sb.from('avvisi').update({fissato:!a.fissato}).eq('id',a.id);await loadBach();renderBach();});
      bx.children[2].addEventListener('click',()=>ask('Eliminare «'+a.titolo+'»?','Elimina',async()=>{await CTX.sb.from('avvisi').delete().eq('id',a.id);await loadBach();renderBach();}));c.appendChild(bx);}
    g.appendChild(c);});el.appendChild(g);if(!AVV.length)el.appendChild(h('<div class="card soon"><p>Nessuna comunicazione in bacheca.</p></div>'));}
function nuovoAvviso(){const ppl=Object.values(PEOPLE).filter(p=>p.id!==CTX.user.id);
  const d=sheet('Pubblica in bacheca','<div class="ctl"><label for="av_k">Tipo</label><select id="av_k">'+TIPI_AVV.map(t=>'<option>'+t+'</option>').join('')+'</select></div><div class="ctl"><label for="av_t">Oggetto</label><input type="text" id="av_t"></div><div class="ctl"><label for="av_x">Testo</label><textarea id="av_x" style="min-height:140px"></textarea></div><div class="ctl"><label for="av_f">Allegato</label><input type="file" id="av_f"></div><div class="lab">Per chi</div><div class="seg wrap" id="av_d"><button type="button" data-v="tutti" aria-pressed="true">Tutti</button><button type="button" data-v="aree" aria-pressed="false">Alcune aree</button><button type="button" data-v="persone" aria-pressed="false">Alcune persone</button></div><div class="checks" id="av_a" hidden>'+SEZ.map(s=>'<label><input type="checkbox" value="'+s.k+'"> '+esc(s.n)+'</label>').join('')+'</div><div class="checks" id="av_p" hidden>'+ppl.map(p=>'<label><input type="checkbox" value="'+p.id+'"> '+esc(p.nome||p.email)+'</label>').join('')+'</div><label class="ck"><input type="checkbox" id="av_fi"> Metti in evidenza (in alto)</label><label class="ck"><input type="checkbox" id="av_im"> Importante (notifica urgente)</label><label class="ck"><input type="checkbox" id="av_cf"> Chiedi la conferma di lettura</label>','Pubblica',async(x)=>{
    const t=x.querySelector('#av_t').value.trim();if(!t){x.querySelector('.smsg').textContent='Scrivi l’oggetto.';return false;}const v=x.querySelector('#av_d [aria-pressed="true"]').dataset.v;
    const f=x.querySelector('#av_f').files[0];const al=f?[await carica(f,'bacheca/'+CTX.user.id)]:[];
    const o={titolo:t,tipo:x.querySelector('#av_k').value,testo:x.querySelector('#av_x').value.trim()||null,allegati:al,tutti:v==='tutti',aree:v==='aree'?[...x.querySelectorAll('#av_a input:checked')].map(i=>i.value):[],utenti:v==='persone'?[...x.querySelectorAll('#av_p input:checked')].map(i=>i.value):[],fissato:x.querySelector('#av_fi').checked,importante:x.querySelector('#av_im').checked,conferma:x.querySelector('#av_cf').checked};
    if(!o.tutti&&!o.aree.length&&!o.utenti.length){x.querySelector('.smsg').textContent='Scegli a chi è rivolto.';return false;}
    const {error}=await CTX.sb.from('avvisi').insert(o);if(error)throw new Error(error.message);await loadBach();renderBach();stEl.textContent='Pubblicato: i destinatari ricevono una notifica.';});
  d.querySelectorAll('#av_d button').forEach(b=>b.addEventListener('click',()=>{d.querySelectorAll('#av_d button').forEach(z=>z.setAttribute('aria-pressed',String(z===b)));d.querySelector('#av_a').hidden=b.dataset.v!=='aree';d.querySelector('#av_p').hidden=b.dataset.v!=='persone';}));}

/* --- Home: bacheca, chat, pagamenti --- */
function extraHome(g){const daL=AVV.filter(a=>!letto(a)),fis=AVV.filter(a=>a.fissato);
  if(AVV.length){const w=h('<section class="w"><div class="wh"><b>Bacheca</b><button type="button" class="lnk2" data-go="p-bach">Apri</button></div>'+(daL.length?'<p class="neg" style="margin:0"><b>'+daL.length+(daL.length===1?' comunicazione nuova':' comunicazioni nuove')+'</b></p>':'')+fis.concat(AVV.filter(a=>!a.fissato)).slice(0,3).map(a=>'<div class="rq"><div><b>'+esc(a.titolo)+'</b><span>'+esc(a.tipo)+' · '+new Date(a.quando).toLocaleDateString('it-IT')+'</span></div></div>').join('')+'</section>');g.appendChild(w);}
  const n=CONV.reduce((a,c)=>a+nonLetti(c.id),0);g.appendChild(h('<section class="w"><div class="wh"><b>Chat</b><button type="button" class="lnk2" data-go="p-chat">Apri</button></div><p style="margin:0">'+(n?'<b>'+n+(n===1?' messaggio nuovo':' messaggi nuovi')+'</b>':'Nessun messaggio nuovo.')+'</p></section>'));
  if(respPag()===CTX.user.id||canV('v-pag')){const X=righeRate();const dc=X.filter(x=>statoRata(x.p)[0]==='In attesa di conferma').length,sc=X.filter(x=>['In scadenza','In ritardo'].includes(statoRata(x.p)[0]));
    if(dc||sc.length)g.appendChild(h('<section class="w"><div class="wh"><b>Pagamenti ai fornitori</b><button type="button" class="lnk2" data-go="v-pag">Apri</button></div>'+(dc?'<p style="margin:0"><b>'+dc+' da confermare</b></p>':'')+(sc.length?'<p style="margin:0">'+sc.length+' in scadenza o in ritardo · '+eur(sc.reduce((a,x)=>a+(+x.p.importo||0),0))+'</p>':'')+'</section>'));}
  chatBadge();}

/* --- tempo reale per chat e bacheca --- */
function liveF8(){if(!CTX.sb)return;CTX.sb.channel('fase8')
  .on('postgres_changes',{event:'INSERT',schema:'public',table:'messaggi'},async p=>{const m=p.new;if(!m||!CONV.find(c=>c.id===m.conv_id)){await loadChat();chatBadge();return;}if((MSG[m.conv_id]||[]).some(x=>x.id===m.id))return;(MSG[m.conv_id]=MSG[m.conv_id]||[]).push(m);
    if(cur==='p-chat'&&CHATOPEN===m.conv_id&&CHATSEL===m.conv_id&&CHATDRAW){CHATDRAW();segnaLetta(m.conv_id);}else if(cur==='p-chat'&&!CHATSEL)renderChat();chatBadge();})
  .on('postgres_changes',{event:'*',schema:'public',table:'avvisi'},async()=>{await loadBach();if(cur==='p-bach'||cur==='p-home')rerender();})
  .subscribe();}
const _dopoAvvio=dopoAvvio;dopoAvvio=function(){_dopoAvvio();liveF8();chatBadge();};

/* --- impostazioni dell'amministratore (responsabili, promemoria, clausole) --- */
function impostazioniCard(){const ppl=Object.values(PEOPLE);const sel=(id,v)=>'<select id="'+id+'"><option value="">Nessuno</option>'+ppl.map(p=>'<option value="'+p.id+'"'+(p.id===v?' selected':'')+'>'+esc(p.nome||p.email)+'</option>').join('')+'</select>';
  const c=h('<section class="card"><h3>Impostazioni</h3><div class="ctl"><label for="im_f">Chi emette le fatture</label>'+sel('im_f',IMP.resp_fatture)+'</div><div class="ctl"><label for="im_p">Chi verifica i pagamenti ai fornitori</label>'+sel('im_p',IMP.resp_pagamenti)+'</div><div class="ctl"><label for="im_g">Promemoria pagamenti: quanti giorni prima (separati da virgola)</label><input type="text" id="im_g" value="'+esc((IMP.giorni_promemoria||[7,1]).join(', '))+'"></div><div class="ctl"><label for="im_c">Clausole del contratto di sponsorizzazione (testo approvato)</label><textarea id="im_c" style="min-height:160px" placeholder="Incolla qui le clausole approvate dall’Associazione. Se resta vuoto il contratto usa una bozza segnata come da far verificare.">'+esc(IMP.clausole_sponsor||'')+'</textarea></div><div class="big-btns"><button type="button" class="bb dark" id="im_s">Salva le impostazioni</button></div><p class="smsg"></p></section>');
  c.querySelector('#im_s').addEventListener('click',async()=>{const g=c.querySelector('#im_g').value.split(/[,;\s]+/).map(Number).filter(n=>n>=0&&n<=60);
    const v=Object.assign({},IMP,{resp_fatture:c.querySelector('#im_f').value||null,resp_pagamenti:c.querySelector('#im_p').value||null,giorni_promemoria:g.length?g:[7,1],clausole_sponsor:c.querySelector('#im_c').value});
    const {error}=await CTX.sb.from('impostazioni').upsert({chiave:'generali',valore:v,aggiornato:new Date().toISOString()});c.querySelector('.smsg').textContent=error?'Errore: '+error.message:'Salvate.';if(!error)IMP=v;});
  return c;}

const _canOpen=canOpen;canOpen=function(id){if(id==='v-femit'&&IMP.resp_fatture===CTX.user.id)return true;if((id==='v-pag'||id==='v-for27')&&IMP.resp_pagamenti===CTX.user.id)return true;return _canOpen(id);};
const _adm=R['s-adm'];R['s-adm']=async function(){await _adm();const el=document.getElementById('s-adm');if(el&&CTX.admin&&cur==='s-adm')el.appendChild(impostazioniCard());};
const _mpn=mePrefNoti;mePrefNoti=function(el){_mpn(el);const c=h('<section class="card"><h3>Riepilogo del mattino</h3><label class="ck"><input type="checkbox"'+(PREF.briefing_push?' checked':'')+'> Ogni mattina ricevi una notifica con le cose del giorno</label></section>');c.querySelector('input').addEventListener('change',async e=>{PREF.briefing_push=e.target.checked;await savePref();stEl.textContent='Preferenze salvate.';});el.insertBefore(c,[...el.children].pop());};
CATN.push(['p-chat','Messaggi in chat'],['p-bach','Bacheca'],['v-pag','Pagamenti ai fornitori'],['v-sp27','Sponsor e fatture']);
const _catDi=catDi;catDi=function(n){const l=String(n.link||'').split('#')[0];if(['p-chat','p-bach','v-pag','v-sp27'].includes(l))return l;return _catDi(n);};
